solution:
fn square(n: Int) -> Int {
  return n * n;
}

fn sum_of_squares(a: Int, b: Int) -> Int {
  let a_squared = square(a);
  let b_squared = square(b);
  return a_squared + b_squared;
}

fn main() -> Int {
  let result = sum_of_squares(3, 4);
  io.println(result);
  return 0;
}
